const navToggle = document.getElementById('nav-toggle');
const mainNav = document.getElementById('main-nav');

navToggle.addEventListener('click', () => {
    const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
    navToggle.setAttribute('aria-expanded', !isExpanded);
    mainNav.classList.toggle('active');
});

// Close mobile menu when a link is clicked
document.querySelectorAll('.nav a').forEach(link => {
    link.addEventListener('click', () => {
        navToggle.setAttribute('aria-expanded', 'false');
        mainNav.classList.remove('active');
    });
});

// Close mobile menu when clicking outside
document.addEventListener('click', (e) => {
    if (!e.target.closest('.header')) {
        navToggle.setAttribute('aria-expanded', 'false');
        mainNav.classList.remove('active');
    }
});

// Newsletter form submission
const newsletterForm = document.getElementById('newsletter-form');
if (newsletterForm) {
    newsletterForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const emailInput = document.getElementById('email-input');
        const email = emailInput.value;

        // Simple validation
        if (!email) {
            alert('Please enter your email address');
            emailInput.focus();
            return;
        }

        // Simulate form submission
        const originalText = e.target.querySelector('button').textContent;
        const button = e.target.querySelector('button');
        button.textContent = 'Subscribed!';
        button.disabled = true;

        // Reset after 2 seconds
        setTimeout(() => {
            emailInput.value = '';
            button.textContent = originalText;
            button.disabled = false;
        }, 2000);
    });
}

// Add to cart functionality
document.querySelectorAll('.product-footer .btn-secondary').forEach(button => {
    button.addEventListener('click', (e) => {
        e.preventDefault();

        const originalText = button.textContent;
        button.textContent = 'Added!';
        button.disabled = true;

        // Update cart badge
        const cartBadge = document.querySelector('.cart-badge');
        if (cartBadge) {
            const currentCount = parseInt(cartBadge.textContent);
            cartBadge.textContent = currentCount + 1;
        }

        // Reset button
        setTimeout(() => {
            button.textContent = originalText;
            button.disabled = false;
        }, 1500);
    });
});

// Smooth scroll for anchor links
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
        const href = this.getAttribute('href');
        if (href !== '#' && document.querySelector(href)) {
            e.preventDefault();
            const target = document.querySelector(href);
            target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    });
});

// Keyboard navigation for card interactions
document.querySelectorAll('.product-card, .editorial-card').forEach(card => {
    card.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
            const link = card.querySelector('a[href]');
            if (link) {
                e.preventDefault();
                link.click();
            }
        }
    });
});

// Handle "Shop Now" button clicks
document.querySelectorAll('.btn-primary, .btn-tertiary').forEach(button => {
    button.addEventListener('click', (e) => {
        // In a real application, this would navigate to the shop page
        console.log('Navigate to shop:', e.target.textContent);
    });
});

// Lazy load images (basic implementation)
if ('IntersectionObserver' in window) {
    const imageObserver = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const img = entry.target;
                if (img.dataset.src) {
                    img.src = img.dataset.src;
                    img.removeAttribute('data-src');
                    observer.unobserve(img);
                }
            }
        });
    });

    document.querySelectorAll('img[data-src]').forEach(img => {
        imageObserver.observe(img);
