        background-color: #2a2a2a;
        border-color: #3a3a3a;
    }

    .product-info h3 a {
        color: #f5f5f5;
    }

    .price {
        color: #f5f5f5;
    }

    .btn-secondary {
        background-color: #3a3a3a;
        color: #f5f5f5;
    }

    .btn-secondary:hover {
        background-color: #4a4a4a;
    }

    .deals-section {
