    border: none;
    border-radius: 6px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    text-decoration: none;
    display: inline-block;
    text-align: center;
}

.btn:focus-visible {
    outline: 2px solid;
    outline-offset: 2px;
}

.btn-primary {
    background-color: #0066cc;
