}

.btn-primary:hover {
    background-color: #0052a3;
}

.btn-primary:focus-visible {
    outline-color: #0066cc;
}

.btn-secondary {
    background-color: #f0f0f0;
    color: #1a1a1a;
}

.btn-secondary:hover {
    background-color: #e0e0e0;
}

.btn-secondary:focus-visible {
    outline-color: #0066cc;
}

.btn-tertiary {
    background-color: transparent;
    color: #0066cc;
