    color: #666;
    margin-bottom: 1rem;
    flex: 1;
}

.product-rating {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 1rem;
    font-size: 0.875rem;
}

.stars {
    color: #ffc107;
}

.rating-count {
    color: #999;
}

.product-footer {
    display: flex;
    justify-content: space-between;
