        grid-template-columns: 1fr;
    }

    .deal-card {
        grid-template-columns: 1fr;
    }

    .deal-image {
        height: 300px;
    }

    .newsletter-container {
        grid-template-columns: 1fr;
        gap: 1.5rem;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form button {
        width: 100%;
    }

    .footer-grid {
