    text-transform: uppercase;
}

.product-info {
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    flex: 1;
}

.product-info h3 {
    margin: 0 0 0.5rem 0;
}

.product-info h3 a {
    color: #1a1a1a;
}

.product-info h3 a:hover {
    color: #0066cc;
}

.product-description {
    font-size: 0.875rem;
    color: #666;
    margin-bottom: 1rem;
    flex: 1;
}

.product-rating {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 1rem;
    font-size: 0.875rem;
}

.stars {
    color: #ffc107;
}

.rating-count {
    color: #999;
}

.product-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
}

.price {
    font-size: 1.25rem;
    font-weight: 700;
    color: #1a1a1a;
}

.product-footer .btn {
    flex: 1;
    padding: 10px 16px;
    font-size: 0.9rem;
}

/* Deals Section */
.deals-section {
    background-color: #f8f8f8;
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.deal-card {
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.3s ease;
    display: grid;
    grid-template-columns: 1fr 1fr;
}

.deal-card:hover {
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
}

.deal-card:focus-within {
    box-shadow: 0 0 0 2px #fff, 0 0 0 4px #0066cc;
}

.deal-image {
    overflow: hidden;
    position: relative;
}

.deal-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.deal-card:hover .deal-image img {
    transform: scale(1.05);
}

.deal-content {
    padding: 2rem;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.deal-content h3 {
    margin: 0 0 0.5rem 0;
}

.discount {
    font-size: 1.5rem;
    font-weight: 700;
    color: #ff6b35;
    margin-bottom: 0.5rem;
}

.deal-description {
    color: #666;
    margin-bottom: 1.5rem;
}

/* Editorial Section */
.editorial-section {
    background-color: #fff;
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 2.5rem;
}

.editorial-card {
    display: flex;
    flex-direction: column;
    transition: transform 0.3s ease;
}

.editorial-card:hover {
    transform: translateY(-4px);
}

.editorial-card:focus-within {
    outline: 2px solid #0066cc;
    outline-offset: 2px;
    border-radius: 4px;
}

.editorial-image {
    overflow: hidden;
    border-radius: 8px;
    margin-bottom: 1.5rem;
}

.editorial-image img {
    width: 100%;
    height: 250px;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.05);
}

.editorial-content h3 {
    margin: 0 0 1rem 0;
}

.editorial-content h3 a {
    color: #1a1a1a;
}

.editorial-content h3 a:hover {
    color: #0066cc;
}

.editorial-meta {
    display: flex;
    gap: 1rem;
    margin-bottom: 0.75rem;
    font-size: 0.875rem;
}

.editorial-category {
    background-color: #f0f0f0;
    padding: 4px 8px;
    border-radius: 4px;
    font-weight: 600;
    color: #0066cc;
}

.editorial-date {
    color: #999;
}

.editorial-content p {
    color: #666;
    margin-bottom: 1rem;
}

.read-more {
    font-weight: 600;
    display: inline-block;
}

/* Newsletter Section */
.newsletter-section {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
