    padding: 60px 20px;
}

.newsletter-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: 3rem;
}

.newsletter-content h2 {
    color: #fff;
    margin: 0;
}

.newsletter-content p {
    opacity: 0.95;
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
}

.newsletter-form input {
    flex: 1;
    padding: 12px 16px;
    border: none;
    border-radius: 6px;
    font-size: 1rem;
    min-width: 0;
}

.newsletter-form input::placeholder {
    color: #999;
}

.newsletter-form input:focus-visible {
    outline: 2px solid #fff;
    outline-offset: 2px;
}

