    color: #fff;
    padding: 60px 20px 20px;
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
    max-width: 1200px;
    margin-left: auto;
    margin-right: auto;
}

.footer-section h3 {
    color: #fff;
    margin-bottom: 1rem;
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: 0.75rem;
}

.footer-section a {
    color: #ccc;
    transition: color 0.2s ease;
    padding: 12px 12px;
    display: inline-flex;
    align-items: center;
    min-width: 24px;
    min-height: 24px;
}

.footer-section a:hover {
    color: #fff;
}

.footer-section a:focus-visible {
    outline: 2px solid #0066cc;
    outline-offset: 2px;
}

.social-links {
    display: flex;
    gap: 1rem;
}

.social-links a {
    padding: 12px 12px;
    display: inline-flex;
    align-items: center;
    min-width: 24px;
    min-height: 24px;
}

.footer-bottom {
    text-align: center;
