const fs = require('fs');
const path = require('path');

(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();

    const htmlPath = path.join(__dirname, 'index.html');
    let htmlContent = fs.readFileSync(htmlPath, 'utf8');

    // Add console logs to debug
    await page.setContent(htmlContent, { waitUntil: 'load' });

    // Check if stylesheets loaded
    const stylesheets = await page.evaluate(() => {
        const links = document.querySelectorAll('link[rel="stylesheet"]');
        return Array.from(links).map(l => ({
            href: l.href,
            loaded: l.sheet ? 'yes' : 'no'
        }));
    });

    console.log('Stylesheets:', JSON.stringify(stylesheets, null, 2));

    // Force reload CSS
    await page.addStyleTag({ path: path.join(__dirname, 'styles.css') });

    const styles2 = await page.evaluate(() => {
        const link = document.querySelector('.nav a');
        const style = window.getComputedStyle(link);
        return {
            padding: style.padding,
            minHeight: style.minHeight
        };
    });

    console.log('After manual CSS load:', JSON.stringify(styles2, null, 2));

    await browser.close();
})();
