const fs = require('fs');
const path = require('path');

(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();

    const htmlPath = path.join(__dirname, 'index.html');
    const cssPath = path.join(__dirname, 'styles.css');
    const jsPath = path.join(__dirname, 'script.js');

    const htmlContent = fs.readFileSync(htmlPath, 'utf8');

    await page.setContent(htmlContent, { waitUntil: 'load' });
    await page.addStyleTag({ path: cssPath });
    await page.addScriptTag({ path: jsPath });
    await page.addScriptTag({ path: '/tmp/axe.min.js' });

    // Run axe accessibility audit
    const results = await page.evaluate(async () => {
        return await window.axe.run({
            runOnly: { type: 'tag', values: ['wcag2aa', 'wcag21aa', 'wcag22aa'] }
        });
    });

    // Manual checks for common issues
    const manualIssues = [];

    // Check form labels
    const formCheck = await page.evaluate(() => {
        const inputs = document.querySelectorAll('input');
        const issues = [];
        inputs.forEach(input => {
            const label = document.querySelector(`label[for="${input.id}"]`);
            const ariaLabel = input.getAttribute('aria-label');
            if (!label && !ariaLabel) {
                issues.push(`Input ${input.id} lacks label`);
            }
        });
        return issues;
    });

    if (formCheck.length > 0) {
        manualIssues.push(...formCheck);
    }

    await browser.close();

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    const report = {
        timestamp: new Date().toISOString(),
        summary: {
            wcagViolations: wcag.length,
            bestPracticeWarnings: bp.length,
            passingTests: results.passes.length,
            manualIssues: manualIssues.length
        },
        wcag: wcag.map(v => ({
            id: v.id,
            impact: v.impact,
            description: v.description,
            help: v.help,
            targets: v.nodes.map(n => ({ selector: n.target, html: n.html }))
        })),
        bp: bp.map(v => ({
            id: v.id,
            description: v.description,
            targets: v.nodes.map(n => n.target)
        })),
        manualIssues: manualIssues
    };

    console.log(JSON.stringify(report, null, 2));

    process.exit(wcag.length > 0 ? 1 : 0);
})();
