    align-items: center;
    min-width: 24px;
    min-height: 24px;
}

.footer-section a:hover {
    color: #fff;
}

.footer-section a:focus-visible {
    outline: 2px solid #0066cc;
    outline-offset: 2px;
}

.social-links {
    display: flex;
    gap: 1rem;
}

.social-links a {
    padding: 12px 12px;
    display: inline-flex;
    align-items: center;
    min-width: 24px;
    min-height: 24px;
}

.footer-bottom {
    text-align: center;
    padding-top: 2rem;
    border-top: 1px solid #333;
    color: #999;
    max-width: 1200px;
    margin: 0 auto;
}

/* Responsive Design */
@media (max-width: 768px) {
    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.5rem;
    }

    .header-container {
        padding: 12px 20px;
    }

    .nav {
        display: none;
