    color: #fff;
    padding: 60px 20px;
}

.newsletter-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: 3rem;
}

.newsletter-content h2 {
    color: #fff;
    margin: 0;
}

.newsletter-content p {
    opacity: 0.95;
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
}

.newsletter-form input {
    flex: 1;
    padding: 12px 16px;
    border: none;
    border-radius: 6px;
    font-size: 1rem;
    min-width: 0;
}

.newsletter-form input::placeholder {
    color: #999;
}

.newsletter-form input:focus-visible {
    outline: 2px solid #fff;
    outline-offset: 2px;
}

/* Footer */
.footer {
    background-color: #1a1a1a;
    color: #fff;
    padding: 60px 20px 20px;
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
    max-width: 1200px;
    margin-left: auto;
    margin-right: auto;
}

.footer-section h3 {
    color: #fff;
    margin-bottom: 1rem;
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: 0.75rem;
}

.footer-section a {
    color: #ddd;
    transition: color 0.2s ease;
    padding: 12px 12px;
    display: inline-flex;
    align-items: center;
    min-width: 24px;
    min-height: 24px;
}

.footer-section a:hover {
    color: #fff;
}

.footer-section a:focus-visible {
    outline: 2px solid #0066cc;
    outline-offset: 2px;
}

.social-links {
    display: flex;
    gap: 1rem;
}

.social-links a {
    padding: 12px 12px;
    display: inline-flex;
    align-items: center;
    min-width: 24px;
    min-height: 24px;
}

.footer-bottom {
    text-align: center;
    padding-top: 2rem;
    border-top: 1px solid #333;
    color: #999;
    max-width: 1200px;
    margin: 0 auto;
}

/* Responsive Design */
@media (max-width: 768px) {
    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.5rem;
    }

    .header-container {
        padding: 12px 20px;
    }

    .nav {
        display: none;
        position: absolute;
        top: 60px;
        left: 0;
        right: 0;
        background: #fff;
        border-bottom: 1px solid #e5e5e5;
        flex-direction: column;
        gap: 0;
        margin: 0;
        z-index: 99;
    }

    .nav.active {
        display: flex;
    }

    .nav ul {
        flex-direction: column;
        gap: 0;
        padding: 1rem;
    }

    .nav a {
        padding: 0.75rem;
    }

    .nav-toggle {
        display: flex;
    }

    .logo-text {
        display: none;
    }

    .hero {
        padding: 60px 20px;
    }

    .hero-content h1 {
        font-size: 2rem;
    }

    .hero-content p {
        font-size: 1rem;
    }

    .section {
        padding: 60px 20px;
    }

    .section-header {
        flex-direction: column;
        gap: 1rem;
        align-items: flex-start;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: 1.5rem;
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .deal-card {
        grid-template-columns: 1fr;
    }

    .deal-image {
        height: 300px;
    }

    .newsletter-container {
        grid-template-columns: 1fr;
        gap: 1.5rem;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form button {
        width: 100%;
    }

    .footer-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 480px) {
    h1 {
        font-size: 1.5rem;
    }

    h2 {
        font-size: 1.25rem;
    }

    .hero-content h1 {
        font-size: 1.5rem;
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .product-footer {
        flex-direction: column;
        gap: 0.75rem;
    }

    .product-footer .btn {
        width: 100%;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
        gap: 1.5rem;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }
}

/* High Contrast Mode Support */
@media (prefers-contrast: more) {
    .btn-secondary {
        border: 2px solid #1a1a1a;
    }

    .nav-toggle {
        border: 2px solid #1a1a1a;
    }
}

/* Reduced Motion Support */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* Dark Mode Support */
@media (prefers-color-scheme: dark) {
    body {
        background-color: #1a1a1a;
        color: #f5f5f5;
    }

    .header {
        background-color: #2a2a2a;
        border-bottom-color: #3a3a3a;
    }

    .logo a {
        color: #f5f5f5;
    }

    .nav a {
        color: #f5f5f5;
    }

    .product-card,
    .deal-card {
        background-color: #2a2a2a;
        border-color: #3a3a3a;
    }

    .product-info h3 a {
        color: #f5f5f5;
    }

    .price {
        color: #f5f5f5;
    }

    .btn-secondary {
        background-color: #3a3a3a;
        color: #f5f5f5;
    }

    .btn-secondary:hover {
        background-color: #4a4a4a;
    }

    .deals-section {
        background-color: #1a1a1a;
    }

    .nav {
        background-color: #2a2a2a;
        border-bottom-color: #3a3a3a;
    }

    .footer {
        background-color: #0a0a0a;
        border-top-color: #2a2a2a;
    }

    .footer-bottom {
        border-top-color: #2a2a2a;
    }
}
