            const style = window.getComputedStyle(el);
            const bg = style.backgroundColor;
            if (bg !== 'rgba(0, 0, 0, 0)') {
                colors.push({
                    element: el.tagName,
                    className: el.className,
                    bg: bg
                });
            }
            el = el.parentElement;
        }

        return {
            linkColor: window.getComputedStyle(linkedin).color,
            hierarchy: colors
        };
    });

    console.log(JSON.stringify(info, null, 2));

    await browser.close();
})();
