    border-radius: 4px;
}

.editorial-image {
    overflow: hidden;
    border-radius: 8px;
    margin-bottom: 1.5rem;
}

.editorial-image img {
    width: 100%;
    height: 250px;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.05);
}

.editorial-content h3 {
    margin: 0 0 1rem 0;
}

.editorial-content h3 a {
    color: #1a1a1a;
    display: block;
    padding: 8px 4px;
    min-height: 24px;
    line-height: 1.2;
}

.editorial-content h3 a:hover {
    color: #0066cc;
}

.editorial-meta {
    display: flex;
    gap: 1rem;
    margin-bottom: 0.75rem;
    font-size: 0.875rem;
}

.editorial-category {
    background-color: #f0f0f0;
    padding: 4px 8px;
