    .product-footer {
        flex-direction: column;
        gap: 0.75rem;
    }

    .product-footer .btn {
        width: 100%;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
        gap: 1.5rem;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }
}

