    bottom: -2px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: #0066cc;
    transition: width 0.2s ease;
}

.nav a:hover:after,
.nav a:focus-visible:after {
    width: 100%;
}

/* Nav Toggle Button */
.nav-toggle {
    display: none;
    flex-direction: column;
    background: none;
    border: none;
    cursor: pointer;
    gap: 4px;
    padding: 4px;
}

.nav-toggle span {
