const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();

    const htmlPath = path.join(__dirname, 'index.html');
    const cssPath = path.join(__dirname, 'styles.css');

    let htmlContent = fs.readFileSync(htmlPath, 'utf8');
    const cssContent = fs.readFileSync(cssPath, 'utf8');

    htmlContent = htmlContent.replace('</head>', '<style>' + cssContent + '</style></head>');

    await page.setContent(htmlContent, { waitUntil: 'load' });

    const info = await page.evaluate(() => {
        const linkedin = document.querySelector('a[aria-label="ModernShop on LinkedIn"]');
        const rect = linkedin.getBoundingClientRect();
        const style = window.getComputedStyle(linkedin);

        return {
            visible: rect.width > 0 && rect.height > 0,
            display: style.display,
            visibility: style.visibility,
            opacity: style.opacity,
            width: rect.width,
            height: rect.height,
            x: rect.x,
            y: rect.y,
            color: style.color,
            getPropertyValue: style.getPropertyValue('--text-color') || 'not set'
        };
    });

    console.log(JSON.stringify(info, null, 2));

    await browser.close();
})();
