    justify-content: space-between;
    max-width: 1200px;
    margin: 0 auto;
    padding: 16px 20px;
}

.logo {
    display: flex;
    align-items: center;
    text-decoration: none;
}

.logo a {
    display: flex;
    align-items: center;
    gap: 8px;
    color: inherit;
    font-size: 1.25rem;
    font-weight: 700;
    color: #1a1a1a;
}

.logo a:focus-visible {
    border-radius: 4px;
}

.logo-text {
    letter-spacing: -0.5px;
}

.logo svg {
    color: #0066cc;
}

/* Navigation */
.nav {
    display: flex;
    gap: 2rem;
    flex: 1;
    margin: 0 2rem;
}

.nav ul {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav li {
    display: flex;
    align-items: center;
}

.nav a {
    font-weight: 500;
    color: #1a1a1a;
    transition: color 0.2s ease;
    position: relative;
    padding: 12px 12px;
    display: inline-block;
    line-height: 1;
    min-height: 24px;
    min-width: 24px;
}

.nav a:after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: #0066cc;
    transition: width 0.2s ease;
}

.nav a:hover:after,
.nav a:focus-visible:after {
    width: 100%;
}

/* Nav Toggle Button */
.nav-toggle {
    display: none;
    flex-direction: column;
    background: none;
    border: none;
    cursor: pointer;
    gap: 4px;
    padding: 4px;
}

.nav-toggle span {
    width: 24px;
    height: 2px;
    background-color: #1a1a1a;
    transition: all 0.3s ease;
    border-radius: 1px;
}

.nav-toggle[aria-expanded="true"] span:nth-child(1) {
    transform: translateY(10px) rotate(45deg);
}

.nav-toggle[aria-expanded="true"] span:nth-child(2) {
    opacity: 0;
}

.nav-toggle[aria-expanded="true"] span:nth-child(3) {
    transform: translateY(-10px) rotate(-45deg);
}

.nav-toggle:focus-visible {
    outline: 2px solid #0066cc;
    outline-offset: 2px;
    border-radius: 4px;
}

/* Header Actions */
.header-actions {
    display: flex;
    gap: 1rem;
    align-items: center;
}

.icon-button {
    background: none;
    border: none;
    cursor: pointer;
    padding: 8px;
