    border: 1px solid #0066cc;
}

.btn-tertiary:hover {
    background-color: #f0f7ff;
}

.btn-tertiary:focus-visible {
    outline-color: #0066cc;
}

/* Hero Section */
.hero {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: #fff;
    padding: 120px 20px;
    text-align: center;
}

.hero-content h1 {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.hero-content p {
    font-size: 1.25rem;
    margin-bottom: 2rem;
